'use strict';
// Optional authoritative connection. Guest saves stay local and are never uploaded.
let onlineToken='',onlineBase='',onlineClient=onlineStore('sessionStorage','fernvale.client')||crypto.randomUUID(),onlinePoll=null,onlineInputs=null,onlineSending=false,onlineSequence=0,onlineApplied=0;
function onlineStore(scope,key,value){try{const store=globalThis[scope];if(value===undefined)return store.getItem(key);if(value===null)store.removeItem(key);else store.setItem(key,value)}catch{}return null}
onlineStore('sessionStorage','fernvale.client',onlineClient);
globalThis.onlineConnected=false;
const onlineOriginal={castWeaponSkill,returnTown,pauseGame,save,press,beginStage,enterTown,castSupportSkill,equipPooledSkill,usePotion,tradePotion,buyShopBoxes,learnOrUpgradeWeaponSkill,equipOwnedGear,spendAP,finishBoxOpening,useAdvancementMark,openGM,commitSelectedSale,activateAutoTicket,buyAutoTickets};
const onlineButton=document.createElement('button');onlineButton.id='onlineLoginBtn';onlineButton.textContent='ออนไลน์ / Auto Farm (ทดสอบ)';onlineButton.onclick=openOnlineLogin;document.querySelector('.main-menu').append(onlineButton);
const autoButton=document.createElement('button');autoButton.id='autoFarmBtn';autoButton.className='auto-farm-button';autoButton.textContent='AUTO';autoButton.onclick=openAutoPanel;$('playScreen').append(autoButton);
function onlineURL(value){const u=new URL(value||location.origin);if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error('ใช้ URL เซิร์ฟเวอร์ http/https');if(u.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw Error('เซิร์ฟเวอร์สาธารณะต้องใช้ HTTPS');return u.origin}
async function onlineRequest(route,body){const res=await fetch(onlineBase+route,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(onlineToken?{Authorization:'Bearer '+onlineToken}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(8000)});let data;try{data=await res.json()}catch{throw Error('ยังไม่พบเซิร์ฟเวอร์เกมที่ URL นี้')}if(!res.ok)throw Error(data.error||'เชื่อมต่อเซิร์ฟเวอร์ไม่ได้');return data}
function applyOnlinePacket(packet,seq){if(seq<onlineApplied)return;onlineApplied=seq;const s=StateCodec.decode(packet.state);Object.assign(player,s.player);run=s.run;platforms=s.platforms;ladders=s.ladders;monsters=s.monsters;drops=s.drops;shots=s.shots;effects=s.effects;texts=s.texts;time=s.time;supportState=s.supportState;swordSwipes=s.swordSwipes;swordWaves=s.swordWaves;activeProjectiles=s.activeProjectiles;activeFields=s.activeFields;activeSummons=s.activeSummons;activeVisuals=s.activeVisuals;activeDash=s.activeDash;autoSession=s.autoSession;if(run?.trial)Object.assign(TRIAL,BOSS_STAGES.find(b=>b.id===run.id));
 interactables=player.map==='town'?[{kind:'npc',x:140,y:285,radius:55,action:openPotionShop},{kind:'npc',x:880,y:420,radius:48,action:()=>toast('GM ใช้ได้เฉพาะเล่นในเครื่อง')},{kind:'portal',x:900,y:285,radius:48,action:openStages}]:[{kind:'portal',x:50,y:420,radius:42,action:()=>onlineCommand({type:'town'})},{kind:'portal',x:worldWidth()-100,y:420,radius:65,action:()=>onlineCommand({type:'town'})}];
 camera=gameCameraTarget();updateUI();autoButton.textContent=(autoFarmActive()?'AUTO · ':'AUTO ')+autoTimeText(player.autoFarm.seconds);autoButton.classList.toggle('running',autoFarmActive());const clock=$('autoFarmClock');if(clock)clock.textContent=autoTimeText(player.autoFarm.seconds);
}
async function onlineCommand(command,{quiet=false}={}){if(!onlineConnected)return false;const seq=++onlineSequence;try{const packet=await onlineRequest('/api/command',{client:onlineClient,command,actionId:crypto.randomUUID()});applyOnlinePacket(packet,seq);return true}catch(e){if(!quiet)toast(e.message);return false}}
function startOnline(packet){onlineConnected=true;keys={};activeSlot=-1;closeModal();switchScreen('play');applyOnlinePacket(packet,++onlineSequence);clearInterval(onlinePoll);clearInterval(onlineInputs);let polling=false;
 onlinePoll=setInterval(async()=>{if(polling)return;polling=true;const seq=++onlineSequence;try{applyOnlinePacket(await onlineRequest('/api/state'),seq)}catch(e){autoButton.textContent='AUTO · ขาดการเชื่อมต่อ';autoButton.title='เซิร์ฟเวอร์อาจยังฟาร์มอยู่ โปรดเชื่อมต่อเพื่อตรวจสอบ'}finally{polling=false}},200);
 onlineInputs=setInterval(async()=>{if(onlineSending||autoFarmActive())return;onlineSending=true;try{await onlineCommand({type:'input',keys:paused||document.hidden?[]:Object.keys(keys).filter(k=>keys[k])},{quiet:true})}finally{onlineSending=false}},100);
 toast('เชื่อมต่อเซิร์ฟเวอร์แล้ว · ตัวละครออนไลน์แยกจากเซฟในเครื่อง');
}
function leaveOnline(){onlineStore('sessionStorage','fernvale.online',null);clearInterval(onlinePoll);clearInterval(onlineInputs);onlinePoll=onlineInputs=null;onlineConnected=false;keys={};autoSession=null;resetSupport();Object.assign(player,fresh());switchScreen('title');toast('ออกจากหน้าจอออนไลน์แล้ว · Auto บนเซิร์ฟเวอร์จะทำงานต่อจนหยุดหรือเวลาหมด')}
function openOnlineLogin(){
 if(onlineConnected){modal('บัญชีออนไลน์','ปิดหน้าจอหรือออกจากเกมแล้ว Auto บนเซิร์ฟเวอร์จะทำงานต่อ หากต้องการหยุด ให้กดหยุด Auto ก่อน',[['กลับ',closeModal],['ออกจากหน้าจอออนไลน์',()=>{closeModal();leaveOnline()}]]);return}
 const body=document.createElement('form');body.className='online-form';body.onsubmit=e=>e.preventDefault();
 body.innerHTML='<p>ระบบออนไลน์รุ่นทดสอบ · ยังไม่มีเซิร์ฟเวอร์สาธารณะ · ตัวละครใหม่แยกจากเซฟในเครื่อง</p><label>URL เซิร์ฟเวอร์<input id="onlineServer" type="url" placeholder="https://…" autocomplete="url"></label><label>ชื่อบัญชี<input id="onlineUsername" autocomplete="username" maxlength="24"></label><label>รหัสผ่าน (อย่างน้อย 10 ตัว)<input id="onlinePassword" type="password" autocomplete="current-password" maxlength="128"></label><label>อาชีพสำหรับบัญชีใหม่<select id="onlineClass"><option value="warrior">STR · นักรบ</option><option value="shooter">DEX · นักยิง</option><option value="mage">INT · นักเวท</option><option value="rogue">LUK · นักลอบโจมตี</option></select></label><p id="onlineError" role="status"></p>';
 const submit=async register=>{const controls=[...$('modalButtons').querySelectorAll('button')];controls.forEach(b=>b.disabled=true);try{onlineToken='';onlineBase=onlineURL($('onlineServer').value);const health=await onlineRequest('/api/health');if(health.engine!=='fernvale-authoritative')throw Error('URL นี้ไม่ใช่เซิร์ฟเวอร์ Fernvale');onlineToken='';const packet=await onlineRequest(register?'/api/register':'/api/login',{username:$('onlineUsername').value,password:$('onlinePassword').value,baseClass:$('onlineClass').value});onlineToken=packet.token;onlineStore('sessionStorage','fernvale.online',JSON.stringify({base:onlineBase,token:onlineToken}));onlineStore('localStorage','fernvale.online.url',onlineBase);startOnline(packet)}catch(e){$('onlineError').textContent=e.message}finally{controls.forEach(b=>b.disabled=false)}};
 modal('ออนไลน์ / Auto Farm',body,[['เข้าสู่ระบบ',()=>submit(false),true],['สร้างบัญชี',()=>submit(true)]]);$('onlineServer').value=onlineStore('localStorage','fernvale.online.url')||location.origin;
}
function openAutoPanel(){
 const body=document.createElement('div');body.className='auto-panel';const clock=document.createElement('div');clock.className='auto-clock';clock.innerHTML='<small>เวลาคงเหลือ</small><strong id="autoFarmClock"></strong><small>สูงสุด 24 ชั่วโมง</small>';clock.querySelector('strong').textContent=autoTimeText(player.autoFarm.seconds||0);body.append(clock);
 const right=document.createElement('div');right.className='auto-options';const slots=document.createElement('div');slots.className='auto-slots';for(let i=0;i<4;i++){const b=document.createElement('button');b.setAttribute('aria-label','ตั้งสกิล Auto ช่อง '+(i+1));const id=player.autoFarm.skills[i];b.innerHTML='<small>'+(i+1)+'</small><span></span>';b.querySelector('span').textContent=id?WEAPON_SKILLS[id].name:'เลือกสกิล';b.disabled=autoFarmActive();b.onclick=()=>openAutoPicker(i);slots.append(b)}right.append(slots);
 const note=document.createElement('p');note.textContent=onlineConnected?'วนใช้ช่อง 1 → 2 → 3 → 4 · ข้ามช่องที่ใช้ไม่ได้ทันที · ไม่กดบัฟ · ปิดเว็บแล้วเซิร์ฟเวอร์ทำงานต่อ':'ต้องเชื่อมต่อเซิร์ฟเวอร์ก่อนเริ่ม Auto Farm · ปัจจุบันยังไม่มีเซิร์ฟเวอร์สาธารณะ';right.append(note);const actions=document.createElement('div');actions.className='auto-actions';
 const help=document.createElement('button');help.textContent='คำอธิบาย';help.onclick=()=>modal('การ Auto Farm','เลือก Active ได้ 4 ช่องตามลำดับของคุณ หากติด CD หรือ MP ไม่พอจะข้ามทันที ชาร์จจนเต็มและกดสกิลต่อเนื่องครั้งละ 3 วินาที ไม่กดบัฟ ไม่ใช้ยาอัตโนมัติ ฟาร์มเฉพาะด่านปัจจุบัน แพ้หรือเวลาหมดจะหยุด บอสที่ตายแล้วจะไม่เริ่มใหม่\nใบละ 1 ชั่วโมง ราคา 10,000 เงิน ใช้ใบสะสมได้สูงสุด 24 ชั่วโมง',[['กลับ',openAutoPanel]]);
 const toggle=document.createElement('button');toggle.id='autoFarmToggle';toggle.className='primary';toggle.textContent=autoFarmActive()?'หยุด Auto':'เริ่ม Auto';toggle.disabled=!onlineConnected||!autoFarmActive()&&(!run||run.tutorial||run.finished||player.autoFarm.seconds<=0||!player.autoFarm.skills.some(id=>id&&weaponSkillEnabled(id)));toggle.onclick=async()=>{if(await onlineCommand({type:autoFarmActive()?'autoStop':'autoStart'}))openAutoPanel()};actions.append(help,toggle);right.append(actions);
 const ticket=document.createElement('button');ticket.id='useAutoTicket';ticket.textContent='ใช้ใบ Auto Farm · มี '+player.autoFarm.tickets+' ใบ';ticket.disabled=!onlineConnected||!player.autoFarm.tickets||player.autoFarm.seconds+3600>AUTO_MAX_SECONDS;ticket.onclick=async()=>{if(await onlineCommand({type:'autoActivate'}))openAutoPanel()};right.append(ticket);body.append(right);
 modal('Auto Farm'+(run?' · '+(run.trial?TRIAL:stageById(run.id))?.name:''),body,onlineConnected?[['บัญชีออนไลน์',openOnlineLogin]]:[['เชื่อมต่อเซิร์ฟเวอร์',openOnlineLogin]]);$('modal').classList.add('auto-modal');
}
function openAutoPicker(index){const body=document.createElement('div');body.className='auto-picker';const choices=[null,...Object.values(WEAPON_SKILLS).filter(d=>d.kind==='active'&&weaponSkillEnabled(d.id)).map(d=>d.id)];for(const id of choices){const b=document.createElement('button');b.textContent=id?WEAPON_SKILLS[id].name+' · ขั้น '+WEAPON_SKILLS[id].tier:'ว่าง';b.onclick=async()=>{if(onlineConnected){if(await onlineCommand({type:'autoSkill',index,id}))openAutoPanel()}else{setAutoSkill(index,id);openAutoPanel()}};body.append(b)}modal('เลือก Active · Auto ช่อง '+(index+1),body,[['กลับ',openAutoPanel]])}
// Keep all economic/combat mutations on the server while connected.
castWeaponSkill=function(id){if(!onlineConnected)return onlineOriginal.castWeaponSkill(id);const index=player.weaponLoadout.findIndex(row=>row.active[0]===id);if(index>=0)onlineCommand({type:'input',keys:Object.keys(keys).filter(k=>keys[k]),press:'Key'+'QWER'[index]});return false};
returnTown=function(){if(!onlineConnected)return onlineOriginal.returnTown();modal('กลับหมู่บ้าน?','หยุด Auto และออกจากด่าน ของที่ยังอยู่บนพื้นจะหาย',[['กลับหมู่บ้าน',async()=>{if(await onlineCommand({type:'town'}))closeModal()},true]])};
save=function(){if(!onlineConnected)return onlineOriginal.save()};
press=function(code,repeat=false){if(!onlineConnected)return onlineOriginal.press(code,repeat);if(paused||autoFarmActive())return;if((code==='Space'&&!keys.ArrowDown||code==='Interact')&&interact())return;keys[code]=true;if(!repeat)onlineCommand({type:'input',keys:Object.keys(keys).filter(k=>keys[k]),press:code},{quiet:true})};
beginStage=function(id){if(!onlineConnected)return onlineOriginal.beginStage(id);onlineCommand({type:'stage',id}).then(ok=>{if(ok)switchScreen('play')})};
enterTown=function(){if(!onlineConnected)return onlineOriginal.enterTown();onlineCommand({type:'town'})};
castSupportSkill=function(id){if(!onlineConnected)return onlineOriginal.castSupportSkill(id);onlineCommand({type:'input',keys:[],buff:id});return false};
equipPooledSkill=function(id,index=0){if(!onlineConnected)return onlineOriginal.equipPooledSkill(id,index);onlineCommand({type:'equipSkill',id,index}).then(ok=>{if(ok){closeModal();openControlWindow('skill')}});return false};
usePotion=function(kind){if(!onlineConnected)return onlineOriginal.usePotion(kind);onlineCommand({type:'potion',kind});return false};
tradePotion=function(id,buy,count=1){if(!onlineConnected)return onlineOriginal.tradePotion(id,buy,count);if(!buy){toast('การขายออนไลน์ยังไม่เปิด');return false}onlineCommand({type:'buyPotion',id,count}).then(ok=>{if(ok){closeTradePopup();openPotionShop()}});return false};
buyShopBoxes=function(kind,count){if(!onlineConnected)return onlineOriginal.buyShopBoxes(kind,count);onlineCommand({type:'buyBox',kind,count}).then(ok=>{if(ok){closeTradePopup();openPotionShop()}});return false};
learnOrUpgradeWeaponSkill=function(id){if(!onlineConnected)return onlineOriginal.learnOrUpgradeWeaponSkill(id);onlineCommand({type:'upgradeSkill',id}).then(ok=>{if(ok)openWeaponSkillDetail(id)});return false};
equipOwnedGear=function(g){if(!onlineConnected)return onlineOriginal.equipOwnedGear(g);onlineCommand({type:'equipGear',id:g.id}).then(ok=>{if(ok)renderCharacterWindow()});return false};
