openGM=function(){if(!onlineConnected)return onlineOriginal.openGM();toast('GM ใช้ได้เฉพาะเล่นในเครื่อง')};
commitSelectedSale=function(){if(!onlineConnected)return onlineOriginal.commitSelectedSale();toast('การขายออนไลน์ยังไม่เปิด');return false};
