const originalShop=openPotionShop;openPotionShop=function(){originalShop();const stock=document.querySelector('.shop-stock');if(!stock)return;const b=document.createElement('button');b.className='shop-product';b.id='buyAutoTicket';b.textContent='ใบ Auto Farm · 1 ชั่วโมง\n10,000 เงิน';b.onclick=()=>modal('ใบ Auto Farm','1 ใบ = 1 ชั่วโมง · ราคา 10,000 เงิน\nซื้อแล้วกดใช้ในหน้า Auto เพื่อเพิ่มเวลา สูงสุด 24 ชั่วโมง',[['กลับร้าน',openPotionShop],['ซื้อ 1 ใบ',async()=>{if(!onlineConnected){toast('ใบ Auto ใช้กับตัวละครออนไลน์ กรุณาเชื่อมต่อเซิร์ฟเวอร์');return}if(await onlineCommand({type:'autoBuy',count:1}))openPotionShop()},true]]);stock.append(b)};
